SELECT enriched, by_info
FROM dataset_source_contribution
WHERE dataset_key = #{datasetKey} AND source_dataset_key = #{sourceKey}

SELECT coalesce(sum(c.enriched), 0)
FROM dataset_source_contribution c JOIN dataset d ON d.key = c.source_dataset_key
WHERE c.dataset_key = #{datasetKey} AND d.gbif_publisher_key = #{publisherKey}
